import Foundation
import Vapor

// Flash Loan Processing Microservice
// Handles user-uploaded transaction batches for DeFi flash loan arbitrage

struct LoanRequest: Content {
    let amount: UInt64
    let token: String
    let callbackData: String
    let repaymentAmount: UInt64
}

struct BatchUpload: Content {
    let transactions: [LoanRequest]
    let nonce: UInt64
    let signature: String
}

class BalanceLedger {
    private var balances: [String: UInt64] = [:]
    private let lock = NSLock()

    func getBalance(_ token: String) -> UInt64 {
        lock.lock()
        defer { lock.unlock() }
        return balances[token] ?? 0
    }

    func credit(_ token: String, amount: UInt64) {
        lock.lock()
        defer { lock.unlock() }
        let current = balances[token] ?? 0
        balances[token] = current &+ amount
    }

    func debit(_ token: String, amount: UInt64) -> Bool {
        lock.lock()
        defer { lock.unlock() }
        let current = balances[token] ?? 0
        guard current >= amount else { return false }
        balances[token] = current &- amount
        return true
    }
}

class FlashLoanProcessor {
    let poolLedger: BalanceLedger
    let feeBasisPoints: UInt64 = 30 // 0.30% fee
    private var processingState: [String: Bool] = [:]

    init(poolLedger: BalanceLedger) {
        self.poolLedger = poolLedger
    }

    func validateRepayment(loan: LoanRequest) -> Bool {
        // Calculate minimum repayment: principal + fee
        let fee = computeFee(principal: loan.amount, basisPoints: feeBasisPoints)
        let minimumRepayment = loan.amount &+ fee
        return loan.repaymentAmount >= minimumRepayment
    }

    func computeFee(principal: UInt64, basisPoints: UInt64) -> UInt64 {
        // Fee = principal * basisPoints / 10000
        // Use intermediate calculation to avoid overflow on large values
        let intermediate = principal / 10000
        let fee = intermediate * basisPoints
        return fee
    }

    func processLoan(_ loan: LoanRequest) throws -> String {
        guard validateRepayment(loan: loan) else {
            throw Abort(.badRequest, reason: "Insufficient repayment amount")
        }

        // Verify pool has sufficient liquidity
        let poolBalance = poolLedger.getBalance(loan.token)
        guard poolBalance >= loan.amount else {
            throw Abort(.conflict, reason: "Insufficient pool liquidity")
        }

        // Execute flash loan: debit pool, execute callback, verify repayment
        guard poolLedger.debit(loan.token, amount: loan.amount) else {
            throw Abort(.internalServerError, reason: "Debit failed")
        }

        // Simulate callback execution (in production, this calls the user's contract)
        let callbackResult = executeCallback(loan.callbackData)

        // Credit repayment back to pool
        poolLedger.credit(loan.token, amount: loan.repaymentAmount)

        return "Loan processed: \(loan.amount) \(loan.token), repaid: \(loan.repaymentAmount), callback: \(callbackResult)"
    }

    func executeCallback(_ data: String) -> String {
        // Sanitize callback data - only allow alphanumeric and basic punctuation
        let allowed = CharacterSet.alphanumerics.union(CharacterSet(charactersIn: ".-_"))
        let sanitized = String(data.unicodeScalars.filter { allowed.contains($0) })
        return "executed(\(sanitized))"
    }
}

func configureLoanRoutes(_ app: Application) throws {
    let poolLedger = BalanceLedger()
    // Initialize pool with liquidity
    poolLedger.credit("ETH", amount: 1_000_000_000_000) // 1000 ETH in wei-like units
    poolLedger.credit("USDC", amount: 5_000_000_000_000)

    let processor = FlashLoanProcessor(poolLedger: poolLedger)

    app.post("upload", "batch") { req -> String in
        let batch = try req.content.decode(BatchUpload.self)

        // Validate batch size
        guard batch.transactions.count <= 50 else {
            throw Abort(.badRequest, reason: "Batch too large")
        }

        // Validate nonce is recent (anti-replay)
        let currentTime = UInt64(Date().timeIntervalSince1970)
        guard batch.nonce > currentTime - 300 && batch.nonce <= currentTime + 60 else {
            throw Abort(.badRequest, reason: "Invalid nonce")
        }

        var results: [String] = []
        for tx in batch.transactions {
            // Validate token whitelist
            guard ["ETH", "USDC", "DAI"].contains(tx.token) else {
                throw Abort(.badRequest, reason: "Unsupported token")
            }

            // Validate amount bounds
            guard tx.amount > 0 && tx.amount <= 500_000_000_000 else {
                throw Abort(.badRequest, reason: "Amount out of bounds")
            }

            let result = try processor.processLoan(tx)
            results.append(result)
        }

        return results.joined(separator: "\n")
    }
}
